#include <gtest/gtest.h>
#include "serving/request_coordinator.h"
TEST(RequestCoordinatorTest, EnforcesGenerationStageDeadlineAndCancellation){serving::RequestCoordinator c;auto future=std::chrono::steady_clock::now()+std::chrono::seconds(1);ASSERT_TRUE(c.submit(1,2,{{serving::MultimodalPartKind::kText,"question"},{serving::MultimodalPartKind::kImage,"content-id"}},future));EXPECT_FALSE(c.complete(1,1,serving::RequestStage::kEncode));ASSERT_TRUE(c.complete(1,2,serving::RequestStage::kEncode));ASSERT_TRUE(c.complete(1,2,serving::RequestStage::kJoin));ASSERT_TRUE(c.complete(1,2,serving::RequestStage::kPrefill));EXPECT_EQ(c.get(1)->stage,serving::RequestStage::kDecode);EXPECT_TRUE(c.cancel(1,2));EXPECT_EQ(c.get(1)->stage,serving::RequestStage::kCancelled);ASSERT_TRUE(c.submit(2,1,{{serving::MultimodalPartKind::kText,"x"}},future));c.expire(future);EXPECT_EQ(c.get(2)->error,"deadline_exceeded");}
